<body>
    <header>
        <h1>⚔ WASTEDTOKEN MINT ⚔</h1>
        <p class="tagline">Forged in Digital Fire, Cast in Metal</p>
    </header>

    <section class="hero-section">
        <canvas id="coin-hero"></canvas>
    </section>

    <section class="about-section">
        <h2>About the Mint</h2>
        <p>
            WastedToken Mint crafts exquisite physical challenge coins for the most discerning collectors.
            Each coin is minted with precision, featuring intricate relief work, mirror-finish surfaces,
            and reeded edges that invoke the grandeur of centuries-old coinage traditions.
        </p>
        <p>
            Our limited editions combine aesthetic mastery with blockchain authenticity,
            creating tangible digital-age artifacts that hold their value and captivate the eye.
            Own a piece of collectible history.
        </p>
    </section>

    <section class="editions-section">
        <h2>Exclusive Editions</h2>
        <div class="editions-grid">
            <div class="edition" data-edition="bronze" data-state="available">
                <canvas class="edition-canvas"></canvas>
                <h3>Bronze Edition</h3>
                <p>Rich patina finish with classic appeal. Perfect entry point for collectors.</p>
                <button class="buy">Add to Cart</button>
            </div>

            <div class="edition" data-edition="silver" data-state="available">
                <canvas class="edition-canvas"></canvas>
                <h3>Silver Edition</h3>
                <p>Mirror-polished surface with brilliant luster. The collector's standard.</p>
                <button class="buy">Add to Cart</button>
            </div>

            <div class="edition" data-edition="gold" data-state="sold-out">
                <canvas class="edition-canvas"></canvas>
                <h3>Gold Edition</h3>
                <p>SOLD OUT. Ultra-premium 24k plating. Available again next cycle.</p>
                <button class="buy" disabled>SOLD OUT</button>
            </div>

            <div class="edition" data-edition="black" data-state="coming-soon">
                <canvas class="edition-canvas"></canvas>
                <h3>Black Obsidian</h3>
                <p>Minting next winter. Onyx-black finish with ghosted relief work.</p>
                <button class="buy" disabled>Winter 2025</button>
            </div>
        </div>
    </section>

    <footer>
        <p>&copy; 2024 WastedToken Mint. All coins authenticated and individually numbered.</p>
    </footer>

    <script>
        // Coin rendering engine
        class CoinRenderer {
            constructor(canvas, options = {}) {
                this.canvas = canvas;
                this.ctx = canvas.getContext('2d');
                this.w = canvas.width;
                this.h = canvas.height;
                this.centerX = this.w / 2;
                this.centerY = this.h / 2;
                this.coinRadius = Math.min(this.w, this.h) * 0.35;
                this.isHero = options.isHero !== false;
                this.edition = options.edition || 'bronze';
                this.time = 0;
            }

            getMetalColor(edition, intensity = 1.0) {
                const colors = {
                    bronze: { base: '#8B4513', light: '#D4A574' },
                    silver: { base: '#C0C0C0', light: '#F5F5F5' },
                    gold: { base: '#B8860B', light: '#FFD700' },
                    black: { base: '#1a1a1a', light: '#404040' }
                };
                const color = colors[this.edition] || colors.bronze;
                return color;
            }

            render(time) {
                this.time = time;
                this.ctx.clearRect(0, 0, this.w, this.h);

                // Main rotation: spin around Y axis (0 to 1 = full rotation)
                // Secondary flip: flip around X axis (0-0.5 shows front, 0.5-1 shows back)
                const spinAngle = time * Math.PI * 2; // Full rotation
                const flipAmount = time; // 0 to 1

                // Flip ranges: 0-0.25 front tilted, 0.25-0.5 front face down, 
                // 0.5-0.75 back tilted up, 0.75-1 back face shown
                let perspective = 1;
                if (flipAmount < 0.25) {
                    perspective = flipAmount / 0.25; // 0 to 1: front tilting
                } else if (flipAmount < 0.5) {
                    perspective = 1 - (flipAmount - 0.25) / 0.25; // 1 to 0: front rotating away
                } else if (flipAmount < 0.75) {
                    perspective = (flipAmount - 0.5) / 0.25; // 0 to 1: back tilting in
                } else {
                    perspective = 1 - (flipAmount - 0.75) / 0.25; // 1 to 0: back rotating away
                }

                // Determine which face to show
                const showingBack = flipAmount >= 0.5;

                // Save context
                this.ctx.save();

                // Apply 3D-like perspective transformation
                const skewY = Math.sin(spinAngle) * perspective * 0.3;
                this.ctx.transform(1, 0, 0, Math.cos(Math.PI * flipAmount), 0, 0);

                // Draw coin
                this.drawCoin(spinAngle, showingBack, perspective);

                this.ctx.restore();
            }

            drawCoin(spinAngle, showingBack, perspective) {
                // Coin body with depth
                const gradient = this.ctx.createRadialGradient(
                    this.centerX - 50, this.centerY - 50, 0,
                    this.centerX, this.centerY, this.coinRadius * 1.5
                );

                const colors = this.getMetalColor(this.edition);

                if (this.edition === 'black') {
                    gradient.addColorStop(0, '#505050');
                    gradient.addColorStop(0.4, '#1a1a1a');
                    gradient.addColorStop(1, '#0a0a0a');
                } else if (this.edition === 'gold') {
                    gradient.addColorStop(0, '#FFE680');
                    gradient.addColorStop(0.4, '#FFD700');
                    gradient.addColorStop(1, '#B8860B');
                } else if (this.edition === 'silver') {
                    gradient.addColorStop(0, '#FFFFFF');
                    gradient.addColorStop(0.3, '#E8E8E8');
                    gradient.addColorStop(1, '#A9A9A9');
                } else {
                    gradient.addColorStop(0, '#D4A574');
                    gradient.addColorStop(0.4, '#8B4513');
                    gradient.addColorStop(1, '#654321');
                }

                this.ctx.fillStyle = gradient;
                this.ctx.beginPath();
                this.ctx.arc(this.centerX, this.centerY, this.coinRadius, 0, Math.PI * 2);
                this.ctx.fill();

                // Draw coin edge (reeded)
                this.drawReedEdge(spinAngle, perspective);

                // Draw face content
                if (perspective > 0.1) {
                    this.drawFaceContent(showingBack);
                }

                // Specular highlight
                this.drawSpecularHighlight(spinAngle, showingBack);
            }

            drawReedEdge(spinAngle, perspective) {
                const reedCount = 24;
                const reedDepth = this.coinRadius * 0.15;

                for (let i = 0; i < reedCount; i++) {
                    const angle = (i / reedCount) * Math.PI * 2 + spinAngle;
                    const x1 = this.centerX + Math.cos(angle) * this.coinRadius;
                    const y1 = this.centerY + Math.sin(angle) * this.coinRadius;
                    const x2 = this.centerX + Math.cos(angle) * (this.coinRadius + reedDepth * 0.5);
                    const y2 = this.centerY + Math.sin(angle) * (this.coinRadius + reedDepth * 0.5);

                    this.ctx.strokeStyle = `rgba(0, 0, 0, ${0.3 * perspective})`;
                    this.ctx.lineWidth = 2;
                    this.ctx.beginPath();
                    this.ctx.moveTo(x1, y1);
                    this.ctx.lineTo(x2, y2);
                    this.ctx.stroke();
                }

                // Rim shadow
                this.ctx.strokeStyle = `rgba(0, 0, 0, ${0.6 * perspective})`;
                this.ctx.lineWidth = 3;
                this.ctx.beginPath();
                this.ctx.arc(this.centerX, this.centerY, this.coinRadius, 0, Math.PI * 2);
                this.ctx.stroke();
            }

            drawFaceContent(showingBack) {
                this.ctx.save();
                this.ctx.clip(() => {
                    this.ctx.beginPath();
                    this.ctx.arc(this.centerX, this.centerY, this.coinRadius * 0.9, 0, Math.PI * 2);
                    this.ctx.fill();
                });

                if (showingBack) {
                    this.drawBackFace();
                } else {
                    this.drawFrontFace();
                }

                this.ctx.restore();
            }

            drawFrontFace() {
                // WastedToken emblem - stylized W symbol
                this.ctx.fillStyle = 'rgba(0, 0, 0, 0.4)';
                this.ctx.font = 'bold 80px Arial';
                this.ctx.textAlign = 'center';
                this.ctx.textBaseline = 'middle';
                this.ctx.fillText('Ⓦ', this.centerX, this.centerY);

                // Decorative ring
                this.ctx.strokeStyle = 'rgba(0, 0, 0, 0.3)';
                this.ctx.lineWidth = 2;
                this.ctx.beginPath();
                this.ctx.arc(this.centerX, this.centerY, this.coinRadius * 0.75, 0, Math.PI * 2);
                this.ctx.stroke();

                // Text
                this.ctx.fillStyle = 'rgba(0, 0, 0, 0.3)';
                this.ctx.font = 'bold 14px Arial';
                this.ctx.fillText('WASTEDTOKEN MINT', this.centerX, this.centerY + 120);
            }

            drawBackFace() {
                // Token denomination
                this.ctx.fillStyle = 'rgba(0, 0, 0, 0.4)';
                this.ctx.font = 'bold 60px Arial';
                this.ctx.textAlign = 'center';
                this.ctx.textBaseline = 'middle';
                this.ctx.fillText('10,000', this.centerX, this.centerY - 30);

                this.ctx.font = 'bold 24px Arial';
                this.ctx.fillStyle = 'rgba(0, 0, 0, 0.3)';
                this.ctx.fillText('TOKENS', this.centerX, this.centerY + 20);

                // Decorative elements
                this.ctx.strokeStyle = 'rgba(0, 0, 0, 0.2)';
                this.ctx.lineWidth = 1;
                for (let i = 0; i < 3; i++) {
                    const r = 50 + i * 30;
                    this.ctx.beginPath();
                    this.ctx.arc(this.centerX, this.centerY, r, 0, Math.PI * 2);
                    this.ctx.stroke();
                }
            }

            drawSpecularHighlight(spinAngle, showingBack) {
                // Moving specular highlight
                const highlightAngle = spinAngle + (showingBack ? Math.PI : 0);
                const highlightX = this.centerX + Math.cos(highlightAngle) * this.coinRadius * 0.4;
                const highlightY = this.centerY + Math.sin(highlightAngle) * this.coinRadius * 0.2;

                const highlightGradient = this.ctx.createRadialGradient(
                    highlightX, highlightY, 0,
                    highlightX, highlightY, this.coinRadius * 0.3
                );

                highlightGradient.addColorStop(0, 'rgba(255, 255, 255, 0.8)');
                highlightGradient.addColorStop(0.5, 'rgba(255, 255, 255, 0.2)');
                highlightGradient.addColorStop(1, 'rgba(255, 255, 255, 0)');

                this.ctx.fillStyle = highlightGradient;
                this.ctx.beginPath();
                this.ctx.arc(highlightX, highlightY, this.coinRadius * 0.3, 0, Math.PI * 2);
                this.ctx.fill();
            }
        }

        // Hero coin setup
        const heroCanvas = document.getElementById('coin-hero');
        heroCanvas.width = 600;
        heroCanvas.height = 600;

        const heroRenderer = new CoinRenderer(heroCanvas, { isHero: true, edition: 'silver' });

        let animationFrameId = null;
        let isRunning = true;
        let startTime = Date.now();

        function animate() {
            if (isRunning) {
                const elapsed = (Date.now() - startTime) / 1000;
                const t = (elapsed % 4) / 4; // 4 second loop
                heroRenderer.render(t);
            }
            animationFrameId = requestAnimationFrame(animate);
        }

        animate();

        // Edition canvases
        const editionElements = document.querySelectorAll('.edition');
        const editionRenderers = {};

        editionElements.forEach(el => {
            const edition = el.dataset.edition;
            const canvas = el.querySelector('.edition-canvas');
            canvas.width = canvas.offsetWidth;
            canvas.height = canvas.offsetHeight;
            const renderer = new CoinRenderer(canvas, { isHero: false, edition: edition });
            editionRenderers[edition] = { renderer, canvas, el };

            // Static render at specific angles
            const staticT = 0.125; // 45 degree turn
            renderer.render(staticT);
        });

        // Window API for grading
        window.demo = {
            canvas: heroCanvas,
            setTime(t) {
                heroRenderer.render(Math.max(0, Math.min(1, t)));
            },
            pause() {
                isRunning = false;
            }
        };

        // Add to cart handlers
        document.querySelectorAll('.buy:not(:disabled)').forEach(btn => {
            btn.addEventListener('click', function() {
                alert('✓ Added to cart! Continue exploring our collection.');
            });
        });
    </script>
</body>
</html>
